package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type User struct {
	ID       int    `json:"id"`
	Username string `json:"username"`
	Email    string `json:"email"`
	Role     string `json:"role"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

func searchUsers(w http.ResponseWriter, r *http.Request) {
	if r.Method != "GET" {
		http.Error(w, "Method not allowed", 405)
		return
	}

	department := r.URL.Query().Get("dept")
	status := r.URL.Query().Get("status")

	// Basic input length check
	if len(department) > 100 || len(status) > 50 {
		http.Error(w, "Input too long", 400)
		return
	}

	// Sanitize status - only allow known values
	validStatuses := map[string]bool{"active": true, "inactive": true, "pending": true}
	if status != "" && !validStatuses[strings.ToLower(status)] {
		status = "active"
	}

	// Build query - department is user-controlled
	query := fmt.Sprintf(
		"SELECT id, username, email, role FROM users WHERE department = '%s'",
		department,
	)

	if status != "" {
		query += fmt.Sprintf(" AND status = '%s'", status)
	}

	query += " ORDER BY username ASC LIMIT 100"

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var users []User
	for rows.Next() {
		var u User
		if err := rows.Scan(&u.ID, &u.Username, &u.Email, &u.Role); err != nil {
			continue
		}
		users = append(users, u)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(users)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/users/search", searchUsers)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
